def finding(item, n, refs):
    fid, name, primary, required = item
    low = name.lower()
    kinds = [primary, KINDS[(n + 7) % len(KINDS)], KINDS[(n + 16) % len(KINDS)]]
    return {"id": fid, "name": name,
      "description": f"Records {low} as source-qualified instrument context while study, campaign, administration, interview, respondent, consent, sample, response, dataset, analysis, audit and records masters remain external.",
      "source_refs": refs,
      "questions": [
       {"id": f"{fid}-q01", "text": f"What stable identity, version, typed value, scope and explicit unknown establish {low}?", "kind": kinds[0], "answer_data": ["instrument, component and external master identifiers", "typed value, vocabulary, schema, mode or profile version", "unknown, missing, not asked, disputed and not-applicable states"]},
       {"id": f"{fid}-q02", "text": f"Who authored, owns, asserts, tests, reviews, approves, administers, answers or may rely on {low}, for which purpose and under what authority?", "kind": kinds[1], "answer_data": ["actor, agent, role, organization and contact", "purpose, population, authority, consent, policy and access", "conflict, exception, escalation and accountability"]},
       {"id": f"{fid}-q03", "text": f"Which reference, test, effective, administration, response, publication, recorded, ingestion and knowledge times, evidence and uncertainty qualify {low}?", "kind": kinds[2], "answer_data": ["distinct instrument, collection, response and knowledge times", "source, method, evidence, confidence, burden and limitation", "successor, correction, retention and audit"]}],
      "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed instrument data for {low}, qualified by version, purpose, population, mode, authority, time, uncertainty and provenance.", "value_kind": "collection", "cardinality": "1" if required else "0..n", "required": required, "source_refs": refs}],
      "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or successor-versioned instrument evidence for {low}.", "media_or_form": ["logical questionnaire specification assertion", "definition, component, rule, test, binding, approval, correction or projection record"], "serial": True, "identity_strategy": f"Instrument ID plus independent version, component, question, response-domain, rule or artifact ID for {fid}; wording, label, position, date and digest never identify a question alone.", "source_refs": refs}],
      "inline_only_rationale": None}

def structure():
    bundles, n = [], 0
    for bid, bname, rationale, layers in ROWS:
        rendered = []
        for lid, lname, refs, items in layers:
            fs = []
            for item in items:
                n += 1
                fs.append(finding(item, n, refs))
            rendered.append({"id": lid, "name": lname, "description": f"Groups source-qualified questionnaire context for {lname.lower()}.", "source_refs": refs, "findings": fs})
        bundles.append({"id": bid, "name": bname, "description": f"Groups governed questionnaire context for {bname.lower()}.", "rationale": rationale + ".", "source_refs": sorted({r for layer in layers for r in layer[2]}), "layers": rendered})
    return {"bundles": bundles}

